import{_ as l,o as i,c as t,aw as a}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Паттерны проектирования","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/design-patterns/main/info.md","filePath":"wiki/dev-commit/theory/design-patterns/main/info.md"}'),r={name:"wiki/dev-commit/theory/design-patterns/main/info.md"};function o(s,e,m,n,c,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="паттерны-проектирования" tabindex="-1">Паттерны проектирования <a class="header-anchor" href="#паттерны-проектирования" aria-label="Permalink to &quot;Паттерны проектирования&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://refactoring.guru/ru/design-patterns/catalog" target="_blank" rel="noreferrer">https://refactoring.guru/ru/design-patterns/catalog</a> - Refactoring Guru. Каталог паттернов проектирования</li><li><a href="https://www.youtube.com/playlist?list=PLNkWIWHIRwMGzgvuPRFkDrpAygvdKJIE4" target="_blank" rel="noreferrer">https://www.youtube.com/playlist?list=PLNkWIWHIRwMGzgvuPRFkDrpAygvdKJIE4</a> - YouTube Playlist: JavaScript Паттерны</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Design Patterns</p><ul><li><strong>Design Patterns</strong> (паттерны проектирования) - это часто встречающееся решение определённой проблемы при проектировании архитектуры программ</li></ul></div><ul><li>В отличие от готовых функций или библиотек, паттерн нельзя просто взять и скопировать в программу. Паттерн представляет собой не какой-то конкретный код, а общую концепцию решения той или иной проблемы, которую нужно будет ещё подстроить под нужды программы</li><li>Паттерны часто путают с <em>алгоритмами</em>, ведь оба понятия описывают типовые решения каких-то известных проблем. Но если алгоритм - это чёткий набор действий, то паттерн - это высокоуровневое описание решения, реализация которого может отличаться в разных программах</li></ul><h2 id="классификация" tabindex="-1">Классификация <a class="header-anchor" href="#классификация" aria-label="Permalink to &quot;Классификация&quot;">​</a></h2><h3 id="_1-creational-порождающие" tabindex="-1">1. Creational (Порождающие) <a class="header-anchor" href="#_1-creational-порождающие" aria-label="Permalink to &quot;1. Creational (Порождающие)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Порождающие</p><ul><li><strong>Порождающие</strong> - отвечают за удобное и безопасное создание новых объектов или даже целых семейств объектов без внесения в программу лишних зависимостей</li></ul></div><ul><li><em>Singleton</em> (Одиночка) - гарантирует, что у класса есть только один экземпляр, и предоставляет к нему глобальную точку доступа</li><li><em>Constructor</em> (Конструктор) - создание новых объектов определенного типа</li><li><em>Builder</em> (Строитель) - позволяет создавать сложные объекты пошагово. Строитель даёт возможность использовать один и тот же код строительства для получения разных представлений объектов</li><li><em>Prototype</em> (Прототип) - можно создавать объекты, взяв за основу другие объекты</li><li><em>Factory Method</em> (Фабричный метод) - определяет общий интерфейс для создания объектов в суперклассе, позволяя подклассам изменять тип создаваемых объектов (их значения)</li><li><em>Abstract Factory</em> (Абстрактная фабрика) - интерфейс, который группирует другие фабрики, логически связанные друг с другом. Помогает создавать объекты со схожей структурой, но разными данными</li></ul><h3 id="_2-structural-структурные" tabindex="-1">2. Structural (Структурные) <a class="header-anchor" href="#_2-structural-структурные" aria-label="Permalink to &quot;2. Structural (Структурные)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Структурные</p><ul><li><strong>Структурные</strong> - отвечают за построение удобных в поддержке иерархий классов. Показывают различные способы построения связей между объектами</li><li>Внедрение нового функционала, без конфликтов со старым</li></ul></div><ul><li><em>Decorator</em> (Декоратор) - позволяет динамически добавлять объектам новую функциональность, оборачивая их в полезные «обёртки»</li><li><em>Adapter</em> (Адаптер) - позволяет объектам с несовместимыми интерфейсами работать вместе</li><li><em>Facade</em> (Фасад) - предоставляет простой интерфейс к сложной системе классов, библиотеке или фреймворку</li><li><em>Flyweight</em> (Легковес) - позволяет вместить бóльшее количество объектов в отведённую оперативную память. Легковес экономит память, разделяя общее состояние объектов между собой, вместо хранения одинаковых данных в каждом объекте</li><li><em>Proxy</em> (Заместитель) - позволяет подставлять вместо реальных объектов специальные объекты-заменители. Эти объекты перехватывают вызовы к оригинальному объекту, позволяя сделать что-то до или после передачи вызова оригиналу</li><li><em>Bridge</em> (Мост) - разделяет один или несколько классов на две отдельные иерархии - абстракцию и реализацию, позволяя изменять их независимо друг от друга</li><li><em>Composite</em> (Компоновщик) - позволяет сгруппировать объекты в древовидную структуру, а затем работать с ними так, как будто это единичный объект</li></ul><h3 id="_3-behavioral-поведенческие" tabindex="-1">3. Behavioral (Поведенческие) <a class="header-anchor" href="#_3-behavioral-поведенческие" aria-label="Permalink to &quot;3. Behavioral (Поведенческие)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Поведенческие</p><ul><li><strong>Поведенческие</strong> - эффективное и безопасное взаимодействие между объектами разного типа</li></ul></div><ul><li><em>Observer</em> (Наблюдатель) - создаёт механизм подписки, позволяющий одним объектам следить и реагировать на события, происходящие в других объектах</li><li><em>Chain of Responsibility</em> (Цепочка обязанностей) - позволяет передавать запросы последовательно по цепочке обработчиков. Каждый последующий обработчик решает, может ли он обработать запрос сам и стоит ли передавать запрос дальше по цепи</li><li><em>Command</em> (Команда) - превращает запросы в объекты, позволяя передавать их как аргументы при вызове методов, ставить запросы в очередь, логировать их, а также поддерживать отмену операций</li><li><em>Iterator</em> (Итератор) - даёт возможность последовательно обходить элементы составных объектов, не раскрывая их внутреннего представления</li><li><em>Mediator</em> (Посредник) - позволяет уменьшить связанность множества классов между собой, благодаря перемещению этих связей в один класс-посредник</li><li><em>State</em> (Состояние) - позволяет объектам менять поведение в зависимости от своего состояния. Извне создаётся впечатление, что изменился класс объекта</li><li><em>Strategy</em> (Стратегия) - пределяет семейство схожих алгоритмов и помещает каждый из них в собственный класс, после чего алгоритмы можно взаимозаменять прямо во время исполнения программы</li><li><em>Template Method</em> (Шаблонный метод) - определяет скелет алгоритма, перекладывая ответственность за некоторые его шаги на подклассы. Паттерн позволяет подклассам переопределять шаги алгоритма, не меняя его общей структуры</li><li><em>Memento</em> (Снимок) - позволяет делать снимки состояния объектов, не раскрывая подробностей их реализации. Затем снимки можно использовать, чтобы восстановить прошлое состояние объектов</li><li><em>Visitor</em> (Посетитель) - позволяет создавать новые операции, не меняя классы объектов, над которыми эти операции могут выполняться</li></ul><h2 id="назначение" tabindex="-1">Назначение <a class="header-anchor" href="#назначение" aria-label="Permalink to &quot;Назначение&quot;">​</a></h2><ul><li><em>Проверенные решения</em>. Использовать готовые решения быстрее, чем писать каждый раз заново</li><li><em>Стандартизация кода</em>. Меньше просчётов при проектировании, используя типовые унифицированные решения, т.к. большинство скрытых проблем уже найдено</li><li><em>Общий программистский словарь</em>. Другие разработчики узнают паттерн по названию</li></ul>',17)])])}const p=l(r,[["render",o]]);export{h as __pageData,p as default};
